// Diagnóstico en vivo de Hyperliquid, en español (de tú). Misma forma que TEXT.en en ../hyperliquid.text.js:
// las cifras llegan ya calculadas y formateadas desde hyperliquid.js. Sin imports.
export default {
  unknownMode: (m) => `No reconocimos este modo de cuenta (${m}). Todavía no sigas la guía; vuelve a intentarlo más tarde.`,
  rpcError: "El nodo de Arbitrum devolvió un error",
  line: {
    perp: (x) => `Cuenta de perps: ${x} USDC`,
    spot: (unified, x) => `${unified ? "Cuenta" : "Spot"}: ${x} USDC`,
    usdh: (x, held, bid) => `Spot: ${x} USDH${held ? ` (${held} en una orden de venta abierta)` : ""}${bid ? ` (precio de compra aprox. ${bid})` : ""}`,
  },
  row: {
    perp: "USDC en tu cuenta de perps",
    spot: (unified) => (unified ? "USDC en tu cuenta" : "USDC en spot"),
    usdh: "USDH (ya no se emite; primero véndelo por USDC)",
    held: (h) => `${h} en una orden de venta abierta`,
    bid: (b) => `precio de compra aprox. ${b}`,
  },
  warn: {
    positions: (n) => `Todavía tienes ${n} ${n === 1 ? "posición abierta" : "posiciones abiertas"}. Primero ${n === 1 ? "ciérrala" : "ciérralas"} en el sitio oficial; esta guía no explica cómo cerrar posiciones.`,
    held: (h) => `Hay ${h} USDH en una orden de venta que no se ha ejecutado, lo más probable porque el precio de compra está por debajo del tuyo. No coloques otra orden. El monto estimado supone que se ejecuta a 0.995.`,
    tooSmall: "Tu USDH vale menos de $10. Puede que esté por debajo del tamaño mínimo de orden, así que quizá no se venda.",
    atBid: (s) => (s ? `Venderlo todo con las ofertas de compra de hoy daría unos ${s.expect} USDC, unos ${s.loss} menos que 1:1` : "Las ofertas de compra de hoy no alcanzan para venderlo todo"),
    lowBid: (bid, atBid) => `El precio de compra del USDH es ${bid}, por debajo del mínimo de 0.995 de la guía, así que espera antes de vender. ${atBid}. También hay una vía oficial: Hyperliquid dice que el emisor del USDH, Bridge, mantiene abierto el canje 1:1 en redeem.bridge.xyz (necesitas una cuenta en Bridge). Abre la guía y toca “¿Te atascaste?” para elegir. El monto estimado no incluye el USDH.`,
    noBids: "Ahora mismo no hay ofertas de compra de USDH, así que no se puede vender. El monto estimado no incluye el USDH.",
    thin: (q) => `Las ofertas de compra a 0.995 o más solo cubren ${q} USDH ahora mismo. El resto esperaría a 0.995 para ejecutarse, así que el monto estimado solo cuenta lo que se puede vender.`,
    others: (n) => `Tu cuenta spot tiene ${n} ${n === 1 ? "otro token" : "otros tokens"}. Esta guía no explica cómo ${n === 1 ? "venderlo" : "venderlos"}.`,
  },
  note: {
    dust: "Hay saldo, pero no alcanza para cubrir la comisión de retiro de 1 USDC.",
    unified: "Cuenta unificada: no hace falta transferir. Vende y luego retira.",
    split: "Cuentas separadas: después de vender, primero pasa el USDC de spot a tu cuenta de perps.",
  },
  fact: {
    mode: (unified) => (unified ? "Modo de cuenta: unificada" : "Modo de cuenta: spot y perps separados"),
    order: (sz, px, m) => `Orden de venta abierta: ${sz} USDH a ${px}, abierta desde hace ${m} min`,
    bid: (b) => `Mejor precio de compra de USDH ahora: ${b}`,
    fills: (n, q, avg) => `Vendido en las últimas 24 horas: ${n} ${n === 1 ? "ejecución" : "ejecuciones"}, ${q} USDH en total, promedio ${avg}`,
    withdraw: (when, usdc, fee, tail) => `Último retiro: solicitado ${when}, ${usdc} USDC por llegar (comisión ${fee})${tail}`,
    arrived: (b) => `; llegó a Arbitrum (bloque ${b})`,
    pending: "; todavía nada en Arbitrum",
    mismatch: "; encontramos la transacción en la blockchain, pero no coincide con una transferencia a ti",
  },
  head: {
    positions: "Primero cierra tus posiciones",
    "usdh-held": "Tu USDH está bloqueado",
    "order-resting": "Tu orden de venta no se ha ejecutado",
    "usdh-dust": "Puedes ignorar lo que sobra",
    "no-bids": "El USDH no se puede vender ahora",
    "low-bid": "El precio de compra es muy bajo. Espera",
    unsold: "Todavía tienes USDH por vender",
    "needs-transfer": "Falta un paso: la transferencia",
    "can-withdraw": "Listo para retirar",
    "too-small": "No alcanza para la comisión",
    "withdraw-arrived": "Tu dinero llegó",
    "withdraw-mismatch": "La llegada no coincide. Detente",
    "withdraw-pending": "Tu retiro va en camino",
    "withdraw-late": "Tu retiro se está demorando",
    nothing: "Nada que retirar",
  },
  say: {
    positions: (n) => `Todavía tienes ${n} ${n === 1 ? "posición abierta" : "posiciones abiertas"}. Primero ${n === 1 ? "ciérrala" : "ciérralas"} en el sitio oficial; esta guía no explica eso. Vuelve cuando termines.`,
    held: (h) => `Hay ${h} USDH bloqueados, pero no vemos ninguna orden de venta abierta. Espera, y toca “Revisar de nuevo” en un minuto.`,
    restingLow: (px, bid) => `Tu orden de venta no se ha ejecutado: tu precio es ${px} y el mejor precio de compra (${bid}) es más bajo. No coloques otra orden.`,
    resting: "Tu orden de venta está abierta y esperando a ejecutarse. No coloques otra; toca “Revisar de nuevo” dentro de un rato.",
    dust: (x) => `Quedan ${x} USDH, que valen menos de $10. No se pueden vender, así que puedes ignorarlos.`,
    noBids: "Ahora mismo no hay ofertas de compra de USDH, así que no se puede vender. Espera; la otra vía oficial es el canje 1:1 con el emisor, Bridge (ver abajo).",
    lowBid: (x, bid) => `Todavía tienes ${x} USDH por vender, pero el mejor precio de compra (${bid}) está por debajo del mínimo de 0.995 de la guía, así que una orden a 0.995 no se ejecutará. Elige una de las tres opciones de abajo.`,
    unsold: (x, bid, thinQ) => `Todavía tienes ${x} USDH por vender. El mejor precio de compra es ${bid}, así que una orden a 0.995 debería ejecutarse de inmediato${thinQ ? ` (aunque las ofertas de compra a 0.995 o más solo cubren ${thinQ})` : ""}.`,
    transfer: (x) => `Todavía hay ${x} USDC en spot. Pásalos a tu cuenta de perps antes de retirar.`,
    withdraw: (x, y) => `Listo para retirar: unos ${x} USDC. Después de la comisión de 1 USDC, llegan unos ${y}.`,
    tooSmall: (x) => `Quedan ${x} USDC. No alcanza para cubrir la comisión de 1 USDC, así que no se puede retirar.`,
    arrived: (when, usdc) => `Tu retiro (solicitado ${when}) llegó: ${usdc} USDC. Busca el USDC en la red Arbitrum de tu billetera.`,
    mismatch: "Encontramos la transacción de este retiro en la blockchain, pero no coincide con una transferencia a ti. No hagas nada más. Lleva capturas de pantalla al soporte oficial de Hyperliquid (abajo).",
    pending: (m) => `Tu retiro va en camino: lo solicitaste hace ${m} min. Hyperliquid dice que llega en 5 minutos como máximo. No vuelvas a retirar; toca “Revisar de nuevo” en unos minutos.`,
    late: (m) => `Pasaron ${m} min desde que retiraste, y no ha llegado nada a Arbitrum. No vuelvas a retirar. Lleva capturas de pantalla al soporte oficial de Hyperliquid (abajo).`,
    nothing: "No hay fondos que retirar ni retiros en las últimas 24 horas.",
  },
  choice: {
    title: "Tú decides:",
    sellHead: (px) => `① Vender al precio de hoy: escribe ${px} como precio`,
    sellBody: (amount, s) => {
      const t = s || {};
      return `Por tus ${amount} USDH, las ofertas de compra de hoy darían unos ${t.expect} USDC, unos ${t.loss} menos que 1:1. Una orden límite no se ejecuta por debajo de este precio, así que recibes al menos unos ${t.min}. Los precios se mueven, así que toca “Revisar de nuevo” justo antes de colocar la orden.`;
    },
    cancelFirst: "Primero cancela tu orden actual: en el sitio oficial, búscala en “Open Orders” y toca “Cancel”. Luego coloca la nueva.",
    sellPick: "Elegir esta opción: usar este precio en la guía",
    sellToast: (cancelFirst, px) => `${cancelFirst ? "Primero cancela tu orden anterior en “Open Orders”. " : ""}La guía ahora usa ${px} como precio. Toca “Revisar de nuevo” antes de colocar la orden; si el precio se mueve, las cifras cambian.`,
    noDepthHead: "① Vender al precio de hoy",
    noDepthBody: "Las ofertas de compra de hoy no alcanzan para todo tu USDH, así que espera.",
    redeemHead: "② Canjear 1:1 con el emisor",
    redeemBody: "Hyperliquid dice que el emisor del USDH, Bridge, mantiene abierto el canje 1:1 en redeem.bridge.xyz. Tendrás que registrarte en Bridge, lo que puede incluir verificación de identidad. Todavía no probamos esta vía, así que sigue los pasos de Bridge. De cualquier forma, ya puedes retirar tu USDC.",
    redeemPick: "Elegir esta opción: por ahora retirar solo el USDC",
    redeemToast: "La guía ahora retira solo tu USDC. Canjea el USDH en el sitio de Bridge, siguiendo sus pasos.",
    waitHead: "③ Esperar",
    waitBody: "El USDH ya no se emite, así que las ofertas de compra pueden seguir bajando. Si prefieres esperar, vuelve más tarde y toca “Revisar de nuevo”.",
  },
};
